import React, { useState, useEffect } from "react";
import { Navbar, Nav, NavDropdown, Button, Container } from "react-bootstrap";
import { Link } from "react-router-dom";
import "./Navigation.css";

const Navigation = () => {
  // State for handling dropdown visibility on hover
  const [openDropdown, setOpenDropdown] = useState(null);
  
  // State to track navbar visibility and the last scroll position
  const [showNavbar, setShowNavbar] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);

  // Handlers for dropdown hover
  const handleMouseEnter = (dropdown) => {
    setOpenDropdown(dropdown);
  };

  const handleMouseLeave = () => {
    setOpenDropdown(null);
  };

  // Function to control navbar visibility on scroll
  const controlNavbar = () => {
    const currentScrollY = window.scrollY;
    if (currentScrollY > lastScrollY) {
      // Scrolling down: hide the navbar
      setShowNavbar(false);
    } else {
      // Scrolling up: show the navbar
      setShowNavbar(true);
    }
    setLastScrollY(currentScrollY);
  };

  useEffect(() => {
    window.addEventListener("scroll", controlNavbar);
    return () => {
      window.removeEventListener("scroll", controlNavbar);
    };
  }, [lastScrollY]);

  return (
    <Navbar
      expand="lg"
      variant="dark"
      style={{
        backgroundColor: "#2d2d2d",
        transition: "transform 0.3s ease",
        transform: showNavbar ? "translateY(0)" : "translateY(-100%)"
      }}
    >
      <Container>
        {/* Brand / Logo */}
        <Navbar.Brand
          as={Link}
          to="/"
          className="fw-bold fs-3"
          style={{ color: "#28c7b7" }}
        >
          Fi
        </Navbar.Brand>

        {/* Toggle for mobile view */}
        <Navbar.Toggle aria-controls="navbarNav" />

        {/* Collapsible nav links */}
        <Navbar.Collapse id="navbarNav" className="justify-content-end">
          <Nav>
            {/* ABOUT US Dropdown */}
            <NavDropdown
              title="ABOUT US"
              id="nav-dropdown-aboutus"
              show={openDropdown === "aboutUs"}
              onMouseEnter={() => handleMouseEnter("aboutUs")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/whats-fi">
                What’s Fi
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/team">
                Team
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/careers">
                Careers
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/contact-us">
                Contact Us
              </NavDropdown.Item>
            </NavDropdown>

            {/* CARDS Dropdown */}
            <NavDropdown
              title="CARDS"
              id="nav-dropdown-cards"
              show={openDropdown === "cards"}
              onMouseEnter={() => handleMouseEnter("cards")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/debit-card">
                Debit Card
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/credit-card">
                Credit Card
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/super-card">
                Super Card
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/fi-secured-cc">
                Fi-Secured CC
              </NavDropdown.Item>
            </NavDropdown>

            {/* FEATURES Dropdown */}
            <NavDropdown
              title="FEATURES"
              id="nav-dropdown-features"
              show={openDropdown === "features"}
              onMouseEnter={() => handleMouseEnter("features")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/ask-fi">
                ASK FI
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/connected-accounts">
                CONNECTED ACCOUNTS
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/accounts">
                ACCOUNTS
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/mutual-funds">
                MUTUAL FUNDS
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/us-stocks">
                US STOCKS
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/us-stock-directory">
                US STOCK DIRECTORY
              </NavDropdown.Item>
            </NavDropdown>

            {/* ACCOUNTS Dropdown */}
            <NavDropdown
              title="ACCOUNTS"
              id="nav-dropdown-accounts"
              show={openDropdown === "accounts"}
              onMouseEnter={() => handleMouseEnter("accounts")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/savings-account">
                Savings Account
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/for-companies">
                For Companies
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/for-individuals">
                For Individuals
              </NavDropdown.Item>
            </NavDropdown>

            {/* RESOURCES Dropdown */}
            <NavDropdown
              title="RESOURCES"
              id="nav-dropdown-resources"
              show={openDropdown === "resources"}
              onMouseEnter={() => handleMouseEnter("resources")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/guides">
                Guides
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/calculators">
                Calculators
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/blogs">
                Blogs
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/loan-calculator">
                Loan Calculator
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/best-budget-directory">
                Best Budget Directory
              </NavDropdown.Item>
            </NavDropdown>

            {/* HELP Dropdown */}
            <NavDropdown
              title="HELP"
              id="nav-dropdown-help"
              show={openDropdown === "help"}
              onMouseEnter={() => handleMouseEnter("help")}
              onMouseLeave={handleMouseLeave}
            >
              <NavDropdown.Item as={Link} to="/faqs">
                FAQs
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/general-inquiries">
                General Inquiries
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/grievance-redressal">
                Grievance Redressal
              </NavDropdown.Item>
              <NavDropdown.Item as={Link} to="/move-your-offices">
                Move Your Offices
              </NavDropdown.Item>
            </NavDropdown>

            {/* DOWNLOAD FI Button */}
            <Button variant="outline-light" className="ms-3">
              DOWNLOAD FI
            </Button>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default Navigation;
